// All backend calls of the Customers page. Docs: ../backend/doc/week1/customer.txt
import api from "../../services/api";
import { optionalField } from "../../utils/body";
import { toMoneyNumber } from "../../utils/money";

// Only the documented fields. `code` is generated by the server and never sent.
function toCustomerBody(form, isEdit) {
  return {
    name: form.name.trim(),
    // Optional text: left out on create when empty; null on edit when emptied (null clears it).
    phone: optionalField(form.phone, isEdit),
    taxNumber: optionalField(form.taxNumber, isEdit),
    commercialRecord: optionalField(form.commercialRecord, isEdit),
    address: optionalField(form.address, isEdit),
    // Money: sent as numbers, never null (an empty field = 0).
    creditLimit: toMoneyNumber(form.creditLimit),
    openingBalance: toMoneyNumber(form.openingBalance),
  };
}

export async function getCustomers() {
  const response = await api.get("/customer");
  return response.data.data;
}

export async function createCustomer(form) {
  const response = await api.post("/customer", toCustomerBody(form, false));
  return response.data.data;
}

export async function updateCustomer(id, form) {
  const response = await api.patch(`/customer/${id}`, toCustomerBody(form, true));
  return response.data.data;
}

export async function deleteCustomer(id) {
  await api.delete(`/customer/${id}`);
}
